From 9a914b07bf195aedd3c42a355b0b53dc7323ebe2 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 12:33:45 +0100
Subject: [PATCH] daemon: Respect lid switch inhibitors from other applications

PowerDevil took over lid handling from logind and then ran the lid action
even when another program held a handle-lid-switch inhibitor. Check for
such inhibitors on lid close and wait until they are released instead.

BUG: 485623
---
 daemon/actions/bundled/handlebuttonevents.cpp | 28 +++++++++++++++++--
 daemon/actions/bundled/handlebuttonevents.h   |  2 ++
 daemon/powerdevilpolicyagent.cpp              | 28 +++++++++++++++++++
 daemon/powerdevilpolicyagent.h                |  8 ++++++
 4 files changed, 63 insertions(+), 3 deletions(-)

diff --git a/daemon/actions/bundled/handlebuttonevents.cpp b/daemon/actions/bundled/handlebuttonevents.cpp
index 5d8a9e753..c5cdb7d41 100644
--- a/daemon/actions/bundled/handlebuttonevents.cpp
+++ b/daemon/actions/bundled/handlebuttonevents.cpp
@@ -107,6 +107,10 @@ HandleButtonEvents::HandleButtonEvents(QObject *parent)

     m_delayedDisplayHotunplugTimer.setSingleShot(true);
     connect(&m_delayedDisplayHotunplugTimer, &QTimer::timeout, this, &HandleButtonEvents::reactToDisplayHotunplug);
+
+    // logind doesn't signal changes to inhibitors, so keep checking while the lid is closed
+    m_lidSwitchInhibitedTimer.setSingleShot(true);
+    connect(&m_lidSwitchInhibitedTimer, &QTimer::timeout, this, &HandleButtonEvents::triggerLidAction);
 }

 HandleButtonEvents::~HandleButtonEvents()
@@ -156,8 +160,10 @@ void HandleButtonEvents::onLidClosedChanged(bool closed)
             return;
         }

-        processAction(m_lidAction);
+        triggerLidAction();
     } else {
+        m_lidSwitchInhibitedTimer.stop();
+
         // When we restore the keyboard brightness before waking up, we shouldn't conflict
         // with dimdisplay or dpms also messing with the keyboard.
         if (m_oldKeyboardBrightness.has_value() && m_oldKeyboardBrightness > 0) {
@@ -166,6 +172,22 @@ void HandleButtonEvents::onLidClosedChanged(bool closed)
     }
 }

+void HandleButtonEvents::triggerLidAction()
+{
+    PolicyAgent::instance()->checkLidSwitchInhibited(this, [this](bool inhibited) {
+        // the lid and output states might've changed while waiting for logind
+        if (!triggersLidAction() || !core()->lidController()->isLidClosed()) {
+            return;
+        }
+        if (inhibited) {
+            qCDebug(POWERDEVIL) << "Lid action was suppressed because another application inhibits lid switch handling";
+            m_lidSwitchInhibitedTimer.start(5s);
+            return;
+        }
+        processAction(m_lidAction);
+    });
+}
+
 void HandleButtonEvents::processAction(PowerDevil::PowerButtonAction action)
 {
     // Basically, we simply trigger other actions :)
@@ -307,7 +329,7 @@ void HandleButtonEvents::checkWakeup()
     // if the lid is still closed and no external monitor is connected,
     // then this must've been an unintended wakeup caused by firmware bugs,
     // hardware quirks or whatever -> just suspend again
-    processAction(m_lidAction);
+    triggerLidAction();
 }

 void HandleButtonEvents::reactToDisplayHotunplug()
@@ -316,7 +338,7 @@ void HandleButtonEvents::reactToDisplayHotunplug()
     if (!triggersLidAction() || !core()->lidController()->isLidClosed()) {
         return;
     }
-    processAction(m_lidAction);
+    triggerLidAction();
 }
 }

