+void PolicyAgent::checkLidSwitchInhibited(QObject *context, const std::function<void(bool)> &callback)
+{
+    if (!m_sdAvailable || !m_managerIface) {
+        callback(false);
+        return;
+    }
+
+    QDBusPendingReply<QList<LogindInhibition>> reply = m_managerIface->asyncCall(QStringLiteral("ListInhibitors"));
+
+    auto *watcher = new QDBusPendingCallWatcher(reply, context);
+    QObject::connect(watcher, &QDBusPendingCallWatcher::finished, context, [callback](QDBusPendingCallWatcher *watcher) {
+        QDBusPendingReply<QList<LogindInhibition>> reply = *watcher;
+        watcher->deleteLater();
+
+        if (reply.isError()) {
+            qCWarning(POWERDEVIL) << "Failed to ask logind for inhibitions" << reply.error().message();
+            callback(false);
+            return;
+        }
+
+        const auto activeInhibitions = reply.value();
+        callback(std::ranges::any_of(activeInhibitions, [](const LogindInhibition &inhibition) {
+            return inhibition.mode == QLatin1String("block") && static_cast<pid_t>(inhibition.pid) != getpid()
+                && inhibition.what.split(QLatin1Char(':')).contains("handle-lid-switch"_L1);
+        }));
+    });
+}
+
 void PolicyAgent::onManagerPropertyChanged(const QString &ifaceName, const QVariantMap &changedProps, const QStringList &invalidatedProps)
 {
     const QString key = QStringLiteral("BlockInhibited");
